import math
from fractions import Fraction
from typing import List

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers: List[int]) -> int:
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

def list_lcm(numbers: List[int]) -> int:
    if not numbers:
        return 1 # LCM of an empty set is often defined as 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

# Highly Composite Numbers (HCNs) sequence
# H1=1, H2=2, H3=4, H4=6, H5=12, H6=24, H7=36, H8=48
HCNs = [1, 2, 4, 6, 12, 24, 36, 48]

def calculate_good_partitions(A: List[int]) -> int:
    n = len(A)
    count = 0
    # We check partitions for k = 1 to n-1
    for k in range(1, n):
        A_k = A[:k]
        B_k = A[k:]

        L_k = list_lcm(A_k)
        G_k = list_gcd(B_k)

        if L_k == G_k:
            count += 1
    return count

# Test for n=6, n=7, n=8
for n in [6, 7, 8]:
    A_n = HCNs[:n]
    M_n = calculate_good_partitions(A_n)
    print(f"M(A_{n}) for n={n}: {M_n}")

